  CONSTRAINT `ck_subscription_plan__price_basis` CHECK (`price_basis` IN ('per_learner_term', 'per_learner_semester', 'flat_term', 'per_campus_term', 'sdaf')),
  CONSTRAINT `ck_subscription_plan__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PLT/config/internal] Operator plan and price-list version for private providers (and the State Enterprise plan)';

CREATE TABLE `subscription_quote` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) COMMENT 'Set once the provider tenant exists',
  `provider_ref` BINARY(16) COMMENT 'Registry provider id (soft) before tenant creation',
  `plan_id` BINARY(16) NOT NULL,
  `learner_estimate` INT UNSIGNED NOT NULL,
  `campus_count` SMALLINT,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `valid_until` DATE NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `document_ref` BINARY(16) COMMENT 'Quote PDF (records zone)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_subscription_quote_tenant_id` (`tenant_id`),
  KEY `ix_subscription_quote_plan_id` (`plan_id`),
  CONSTRAINT `ck_subscription_quote__status` CHECK (`status` IN ('draft', 'sent', 'accepted', 'expired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PLT/transaction/internal] Quote issued to a private provider before subscription acceptance';

CREATE TABLE `tenant` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `parent_id` BINARY(16) COMMENT 'Parent tenant (state for a private provider, country for a state)',
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Stable tenant code, e.g. ng, ng-ab, pvt-ng-ab-000123',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `residency_region_id` BINARY(16) NOT NULL,
  `state_code` VARCHAR(6) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'ISO 3166-2 state for state and private-provider tenants',
  `isolation` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Dedicated schema or pooled schema (MFS §16.3 layer 1)',
  `ops_schema` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'MySQL schema of the tenant''s ops zone',
  `time_zone` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'Africa/Lagos' COMMENT 'IANA time zone applied on display',
  `default_language` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'en-NG',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'NGN',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `activated_at` DATETIME(6),
  `closed_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tenant_code` (`code`),
  KEY `ix_tenant_parent_id` (`parent_id`),
  KEY `ix_tenant_residency_region_id` (`residency_region_id`),
  CONSTRAINT `ck_tenant__kind` CHECK (`kind` IN ('global', 'country', 'state', 'network', 'private_provider', 'institution', 'department', 'sector_registry')),
  CONSTRAINT `ck_tenant__isolation` CHECK (`isolation` IN ('dedicated_schema', 'pooled_schema')),
  CONSTRAINT `ck_tenant__status` CHECK (`status` IN ('proposed', 'provisioning', 'active', 'suspended', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PLT/master/internal] Tenant — data boundary, configuration and billing unit (global, country, state, network, private provider)';

CREATE TABLE `tenant_domain` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL,
  `hostname` VARCHAR(253) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. abia.syntegra.ng or portal.schoolname.ng',
  `is_primary` BOOLEAN NOT NULL DEFAULT FALSE,
  `verified_at` DATETIME(6) COMMENT 'DNS ownership verified',
  `tls_certificate_ref` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci COMMENT 'Certificate manager reference',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tenant_domain_hostname` (`hostname`),
  KEY `ix_tenant_domain_tenant_id` (`tenant_id`),
  CONSTRAINT `ck_tenant_domain__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PLT/config/internal] Hostname that resolves to a tenant at sign-in (tenant is never chosen from a list)';

-- ============================================================================
-- Domain INT — Intelligence and automation — alerts, investigations, improvement, recommendations, early warning, model register, agents, assistant and planning
-- ============================================================================

CREATE TABLE `agent_template` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'register_agent, coverage_agent, fee_agent …',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `watches` TEXT NOT NULL,
  `tools` JSON NOT NULL COMMENT 'Declared typed commands',
  `max_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `human_only_actions` JSON NOT NULL COMMENT 'Hard-wired consequential decisions (cannot exceed A1)',
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_agent_template_code_version` (`code`, `version`),
  CONSTRAINT `ck_agent_template__max_level` CHECK (`max_level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent_template__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Agent library template (16 shipped agents) — triggers, tools, maximum autonomy, limits';

CREATE TABLE `ai_model` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `purpose` TEXT NOT NULL,
  `owner` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `training_data` TEXT NOT NULL,
  `excluded_features` JSON NOT NULL COMMENT 'Protected characteristics excluded from learner-risk features',
  `oversight_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dpia_document_ref` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ai_model_code` (`code`),
  CONSTRAINT `ck_ai_model__oversight_level` CHECK (`oversight_level` IN ('advisory', 'human_in_loop', 'human_on_loop')),
  CONSTRAINT `ck_ai_model__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/master/internal] Model register entry (purpose, owner, data, excluded features, oversight level) — AIX-03';

CREATE TABLE `ai_model_version` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `model_id` BINARY(16) NOT NULL,
  `version_label` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `artifact_uri` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `metrics` JSON NOT NULL,
  `fairness` JSON NOT NULL,
  `drift` JSON,
  `approved_by` BINARY(16),
  `review_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ai_model_version_model_id_version_label` (`model_id`, `version_label`),
  KEY `ix_ai_model_version_approved_by` (`approved_by`),
  CONSTRAINT `ck_ai_model_version__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Model version with metrics, fairness gaps, drift, approval and review date (MLflow-tracked)';

-- ============================================================================
-- Domain AUD — Audit trail, chain anchors and the transactional outbox
-- ============================================================================

CREATE TABLE `audit_anchor` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `chain_id` BINARY(16) NOT NULL,
  `anchor_date` DATE NOT NULL,
  `last_chain_seq` BIGINT NOT NULL,
  `anchor_hash` BINARY(32) NOT NULL,
  `worm_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `verified_at` DATETIME(6),
  `verification_ok` BOOLEAN,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_audit_anchor_chain_id_anchor_date` (`chain_id`, `anchor_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/internal] Daily anchor of an audit chain written to write-once storage, and the nightly verification result';

CREATE TABLE `audit_chain_head` (
  `chain_id` BINARY(16) NOT NULL,
  `lane` SMALLINT NOT NULL,
  `last_seq` BIGINT NOT NULL,
  `last_hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`chain_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/projection/internal] Head of an audit hash chain (last sequence and hash), locked FOR UPDATE by each writer to sequence the chain';

CREATE TABLE `audit_event` (
  `chain_id` BINARY(16) NOT NULL COMMENT 'Tenant id (or the platform chain id in the platform zone)',
  `chain_seq` BIGINT NOT NULL COMMENT 'Monotonic sequence within the chain',
  `occurred_at` DATETIME(6) NOT NULL,
  `event_id` BINARY(16) NOT NULL COMMENT 'UUID v7 of the event',
  `actor_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` BINARY(16),
  `on_behalf_of_user_id` BINARY(16) COMMENT 'Agent X acting for Owner Y',
  `actor_grant_id` BINARY(16) COMMENT 'Active role-at-scope',
  `scope_node_id_at` BINARY(16) COMMENT 'Scope of the record at the time',
  `action` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. learner.update, learner.nin.reveal, safeguarding_case.view, export.bulk',
  `record_kind` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_id` BINARY(16),
  `field_changes` JSON COMMENT '[{field, from, to}] — special-category values as hashes',
  `reason` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `purpose_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Required for restricted/special access',
  `approval_ref` BINARY(16),
  `correlation_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `ip` VARBINARY(16),
  `user_agent` VARCHAR(400) COLLATE utf8mb4_0900_ai_ci,
  `prev_hash` BINARY(32) NOT NULL,
  `hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`chain_id`, `chain_seq`, `occurred_at`),
  KEY `ix_audit_event_record_kind_record_id` (`record_kind`, `record_id`),
  KEY `ix_audit_event_actor_id_occurred_at` (`actor_id`, `occurred_at`),
  CONSTRAINT `ck_audit_event__actor_kind` CHECK (`actor_kind` IN ('user', 'agent', 'api_client', 'system', 'platform_operator'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/restricted] Tamper-evident audit event (append-only, hash-chained per tenant and zone, partitioned by day)'
PARTITION BY RANGE COLUMNS (`occurred_at`) (
  PARTITION p20261001 VALUES LESS THAN ('2026-10-02 00:00:00'),
