-- ============================================================================
-- Domain REG — Education watchdogs, regulators and examination bodies — their dependencies and every institution's regulatory profile
-- ============================================================================

CREATE TABLE `body_dependency` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `from_body_id` BINARY(16) NOT NULL,
  `to_body_id` BINARY(16) NOT NULL,
  `dependency_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `note` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci,
  `data_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_body_dependency_from_body_id_to_body_id_dependency_type` (`from_body_id`, `to_body_id`, `dependency_type`),
  KEY `ix_body_dependency_to_body_id` (`to_body_id`),
  CONSTRAINT `ck_body_dependency__dependency_type` CHECK (`dependency_type` IN ('supervised_by', 'recognises_results_of', 'accredits_with', 'funded_by', 'member_of')),
  CONSTRAINT `ck_body_dependency__data_status` CHECK (`data_status` IN ('verified', 'illustrative', 'to_confirm'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[REG/reference/public] Dependency between two watchdogs (supervised by, recognises the results of, accredits with, funded by, member of)';

CREATE TABLE `regulatory_body` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Matches the regulator code list where one exists, e.g. NUC, WAEC, JAMB',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `body_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `statutory_basis` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci COMMENT 'Establishing law',
  `jurisdiction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `levels` JSON COMMENT 'Education levels the body covers (education_level codes)',
  `functions` TEXT COMMENT 'What the body does for institutions',
  `website` VARCHAR(2048) CHARACTER SET ascii COLLATE ascii_bin,
  `data_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_regulatory_body_code` (`code`),
  CONSTRAINT `ck_regulatory_body__body_type` CHECK (`body_type` IN ('ministry', 'regulator_accreditor', 'examination_body', 'admissions_body', 'curriculum_authority', 'teacher_regulator', 'professional_council', 'funding_agency', 'sector_regulator', 'training_institute')),
  CONSTRAINT `ck_regulatory_body__jurisdiction` CHECK (`jurisdiction` IN ('federal', 'regional', 'state')),
  CONSTRAINT `ck_regulatory_body__data_status` CHECK (`data_status` IN ('verified', 'illustrative', 'to_confirm')),
  CONSTRAINT `ck_regulatory_body__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[REG/reference/public] Education watchdog — ministry, regulator, examination, admission, curriculum, teacher, funding or professional body';


